import marshal
import os
import platform
import sys
import threading
import types
import zlib
from datetime import date
from pathlib import Path

from . import _crypto
from . import _ed25519
from . import _machine

BUILD_ID = "__PYSHELD_BUILD_ID__"
MASTER_KEY_B85 = "__PYSHELD_MASTER_KEY__"
SIGNING_PUBLIC_KEY_B85 = "__PYSHELD_SIGNING_PUBLIC_KEY__"
PYTHON_VERSION = "__PYSHELD_PYTHON_VERSION__"
CIPHER = "__PYSHELD_CIPHER__"
LICENSE_FORMAT = 2

LICENSE_SALT = b"pyshield-license-v1"
LICENSE_AAD_PREFIX = b"pyshield-license:"

_lock = threading.RLock()
_state: dict | None = None


class LicenseError(RuntimeError):
    """Raised when the build's license is missing, invalid or expired."""


def _dist_dir() -> Path:
    return Path(__file__).resolve().parent.parent


def _runtime_dir() -> Path:
    return Path(__file__).resolve().parent


def _license_candidates() -> list[Path]:
    candidates: list[Path] = []
    env = os.environ.get("PYSHELD_LICENSE")
    if env:
        candidates.append(Path(env))
    candidates.append(_dist_dir() / "pyshield.lic")
    candidates.append(_runtime_dir() / "pyshield.lic")
    return candidates


def _read_license() -> tuple[Path, bytes]:
    for path in _license_candidates():
        if path.is_file():
            return path, path.read_bytes()
    locations = ", ".join(str(item) for item in _license_candidates()[:-1])
    raise LicenseError(
        "PyShield license not found; expected pyshield.lic next to manage.py"
        + (f", or PYSHELD_LICENSE ({locations})" if locations else "")
    )


def _license_key() -> bytes:
    master_key = _crypto.b85decode(MASTER_KEY_B85)
    return _crypto.hkdf_sha256(master_key, salt=LICENSE_SALT, info=BUILD_ID.encode("utf-8"), length=32)


